// Package chainledger implements the on-chain data governance core.
//
// This file adds local lineage snapshots: a snapshot freezes one graph as a
// versioned, content-addressed JSON document, and two snapshots can be compared
// read-only. Every byte a snapshot writes is determined solely by the graph's
// semantics — dataset names and their direct upstreams — never by record
// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
// file path.
package chainledger

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
)

// SnapshotFormatVersion is the only on-disk snapshot format understood.
const SnapshotFormatVersion = 1

// SnapshotFile is the on-disk representation of one frozen lineage graph.
//
// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
// verified against Graph on every read; Graph carries the complete graph.
type SnapshotFile struct {
	FormatVersion int       `json:"formatVersion"`
	ContentID     string    `json:"contentId"`
	Graph         GraphFile `json:"graph"`
}

// RootSourceChange reports that one dataset present in BOTH versions reaches a
// different set of root sources. OldRoots and NewRoots are sorted by name and
// never nil, so empty root sets encode as [] rather than null.
type RootSourceChange struct {
	Dataset  string   `json:"dataset"`
	OldRoots []string `json:"oldRoots"`
	NewRoots []string `json:"newRoots"`
}

// CompareReport is the deterministic, read-only diff of two snapshots read in
// the fixed direction old -> new.
//
// NewDatasets and RemovedDatasets list nodes present on only one side.
// ChangedDatasets lists datasets present on both sides whose direct upstream
// set actually changed. AddedRelations and RemovedRelations list every
// directed edge present on only one side, including edges that vanish because
// one endpoint node was removed. RootSourceChanges covers only datasets common
// to both versions whose reachable root set differs; added or removed datasets
// never appear there.
type CompareReport struct {
	NewDatasets       []string           `json:"newDatasets"`
	RemovedDatasets   []string           `json:"removedDatasets"`
	ChangedDatasets   []string           `json:"changedDatasets"`
	AddedRelations    []Relation         `json:"addedRelations"`
	RemovedRelations  []Relation         `json:"removedRelations"`
	RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
}

// contentIDPrefix names the hash algorithm used for content addressing.
const contentIDPrefix = "sha256:"

// canonicalGraph serializes the graph's semantics deterministically: datasets
// sorted by name byte order with sorted, duplicate-free upstream lists, compact
// JSON with no insignificant whitespace. Two semantically equal graphs always
// produce identical bytes.
func canonicalGraph(adj adjacency) ([]byte, error) {
	gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
	return json.Marshal(gf)
}

// computeContentID returns the content identifier of the graph bytes:
// "sha256:" followed by the lowercase hex SHA-256 digest.
func computeContentID(canonical []byte) string {
	sum := sha256.Sum256(canonical)
	return contentIDPrefix + hex.EncodeToString(sum[:])
}

// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
// version 1 and the matching content identifier. It does not mutate graph. The
// returned document and its serialized bytes depend only on graph semantics.
func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
	if err := ValidateGraph(graph); err != nil {
		return nil, err
	}
	adj, err := graphAdjacency(graph)
	if err != nil {
		return nil, err
	}
	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	return &SnapshotFile{
		FormatVersion: SnapshotFormatVersion,
		ContentID:     computeContentID(canonical),
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// MarshalSnapshot serializes a snapshot the same way for every save: indented
// JSON keyed by struct field order, terminated by a single newline.
func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(snap); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
// can distinguish "field absent" from "field present with a zero value"
// (e.g. a missing formatVersion must be rejected rather than read as 0).
type rawSnapshot struct {
	FormatVersion json.RawMessage `json:"formatVersion"`
	ContentID     json.RawMessage `json:"contentId"`
	Graph         json.RawMessage `json:"graph"`
}

// isJSONNull reports whether a raw JSON value is the literal null.
func isJSONNull(raw json.RawMessage) bool {
	return string(bytes.TrimSpace(raw)) == "null"
}

// ParseSnapshot parses and strictly validates one snapshot document: required
// fields must be present and well-typed, no known field may be declared twice
// within the same object (even with identical values, a null first, or a
// spelling equivalent under Unicode case folding or JSON escaping), the
// format version must be supported, the embedded graph must be structurally
// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
// and the content identifier must correspond exactly to the graph. A
// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
// can never be trusted as a version.
func ParseSnapshot(data []byte) (*SnapshotFile, error) {
	if err := checkDuplicateFields(data); err != nil {
		return nil, err
	}
	var raw rawSnapshot
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
	}
	if len(raw.FormatVersion) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
	}
	if len(raw.ContentID) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
	}
	if len(raw.Graph) == 0 {
		return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
	}
	// An explicit JSON null is present-but-untyped and must not be silently
	// treated as a zero value (in particular, graph:null must not read as an
	// empty graph).
	if isJSONNull(raw.FormatVersion) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
	}
	if isJSONNull(raw.ContentID) {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
	}
	if isJSONNull(raw.Graph) {
		return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
	}

	var version int
	if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
	}
	if version != SnapshotFormatVersion {
		return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
	}

	var contentID string
	if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
	}
	if contentID == "" {
		return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
	}

	var gf GraphFile
	if err := json.Unmarshal(raw.Graph, &gf); err != nil {
		return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
	}
	// The embedded graph obeys exactly the same structural rules as a
	// standalone graph file, so the two readers can never judge one graph
	// differently.
	adj, err := validateGraphStructureFromFile(gf.Datasets)
	if err != nil {
		return nil, err
	}

	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	if want := computeContentID(canonical); contentID != want {
		return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
	}

	return &SnapshotFile{
		FormatVersion: version,
		ContentID:     contentID,
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// errAbortScan stops the duplicate-field scan when the document is too
// malformed to keep walking; the regular parse then reports the syntax or
// type error instead.
var errAbortScan = errors.New("chainledger: abort duplicate field scan")

// checkDuplicateFields rejects a snapshot in which a known field is declared
// more than once within the same object: formatVersion, contentId, and graph
// at the top level, datasets inside graph, and name and upstreams inside each
// dataset record. A repeated field is ambiguous — the reader would silently
// keep only one declaration — so the whole snapshot is refused even when the
// duplicates carry identical values, the first is null, or the surviving value
// would pass every other check.
//
// The decoder uses UseNumber so numbers are kept verbatim instead of being
// converted to float64: a perfectly legal JSON number outside the float64
// range (such as 1e400), even one buried in an ignored unknown field's value,
// must not make the decoder error out and abort the whole scan — otherwise an
// unrelated large number placed before a repeated known field would hide that
// duplication. Malformed number syntax still fails and is left to the regular
// parse to report.
//
// Field names are compared after JSON string unescaping and with the same
// Unicode simple case-folding the decoder applies to its case-insensitive
// field lookup (equivalent to strings.EqualFold), so "name", "Name", and
// "name" all collide, and so do spellings that only differ in a fold
// equivalent rune such as "formatVerſion" (long s) and "formatVersion".
// Unknown fields keep their ignore-everything behavior and may repeat freely.
// Documents that are not shaped like a snapshot at all are left to the
// regular parse, which reports the structural problem.
func checkDuplicateFields(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	err := checkTopLevelObject(dec)
	if errors.Is(err, errAbortScan) {
		return nil
	}
	return err
}

// checkGraphFileDuplicateFields applies the same repeated-known-field rule to
// a standalone graph file: datasets may be declared only once in the
// top-level graph object, and name and upstreams only once in each dataset
// record. This keeps UnmarshalGraphFile in lockstep with ParseSnapshot, which
// runs the identical scan on the embedded graph, so preview, apply, and
// snapshot can never disagree about a graph file that repeats a known field.
func checkGraphFileDuplicateFields(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	err := checkGraphValue(dec, "at the top level of the graph")
	if errors.Is(err, errAbortScan) {
		return nil
	}
	return err
}

// checkTopLevelObject scans the top-level snapshot object for repeated
// formatVersion/contentId/graph declarations, descending into graph values.
func checkTopLevelObject(dec *json.Decoder) error {
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		return nil // not an object: the regular parse reports the type error
	}
	seen := make(map[string]bool, 3)
	for dec.More() {
		key, err := scanKey(dec)
		if err != nil {
			return err
		}
		field, known := snapshotField(key)
		if known {
			if seen[field] {
				return duplicateFieldError(field, "at the top level of the snapshot")
			}
			seen[field] = true
		}
		if field == "graph" {
			if err := checkGraphValue(dec, `in "graph"`); err != nil {
				return err
			}
		} else if err := skipValue(dec); err != nil {
			return err
		}
	}
	_, err = scanToken(dec) // closing '}'
	return err
}

// checkGraphValue scans one graph value for a repeated datasets declaration,
// descending into each dataset record of the datasets array. location names
// the graph object itself in the duplicate error ("in \"graph\"" when the
// graph is embedded in a snapshot, the top-level description for a standalone
// graph file).
func checkGraphValue(dec *json.Decoder, location string) error {
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		// Not an object (null, array, scalar): consume any remainder and let
		// the regular parse report the type problem.
		return skipRest(dec, tok)
	}
	seen := false
	for dec.More() {
		key, err := scanKey(dec)
		if err != nil {
			return err
		}
		if strings.EqualFold(key, "datasets") {
			if seen {
				return duplicateFieldError("datasets", location)
			}
			seen = true
			if err := checkDatasetsValue(dec); err != nil {
				return err
			}
		} else if err := skipValue(dec); err != nil {
			return err
		}
	}
	_, err = scanToken(dec) // closing '}'
	return err
}

// checkDatasetsValue scans one datasets array, checking every record that is
// an object for repeated name/upstreams declarations.
func checkDatasetsValue(dec *json.Decoder) error {
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '[' {
		return skipRest(dec, tok) // not an array: the regular parse reports it
	}
	for index := 0; dec.More(); index++ {
		if err := checkDatasetRecord(dec, index); err != nil {
			return err
		}
	}
	_, err = scanToken(dec) // closing ']'
	return err
}

// checkDatasetRecord scans one element of the datasets array. If it is an
// object, name and upstreams must each be declared at most once.
func checkDatasetRecord(dec *json.Decoder, index int) error {
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		return skipRest(dec, tok) // not an object: the regular parse reports it
	}
	seen := make(map[string]bool, 2)
	for dec.More() {
		key, err := scanKey(dec)
		if err != nil {
			return err
		}
		if field, known := datasetField(key); known {
			if seen[field] {
				return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
			}
			seen[field] = true
		}
		if err := skipValue(dec); err != nil {
			return err
		}
	}
	_, err = scanToken(dec) // closing '}'
	return err
}

// duplicateFieldError reports a known field declared twice, naming the field
// and where in the document the repetition occurred.
func duplicateFieldError(field, location string) error {
	return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
}

// snapshotField maps a top-level key to the canonical name of the snapshot
// field it selects, matching the decoder's case-insensitive field lookup.
func snapshotField(key string) (string, bool) {
	switch {
	case strings.EqualFold(key, "formatVersion"):
		return "formatVersion", true
	case strings.EqualFold(key, "contentId"):
		return "contentId", true
	case strings.EqualFold(key, "graph"):
		return "graph", true
	}
	return "", false
}

// datasetField maps a dataset-record key to the canonical name of the record
// field it selects, matching the decoder's case-insensitive field lookup.
func datasetField(key string) (string, bool) {
	switch {
	case strings.EqualFold(key, "name"):
		return "name", true
	case strings.EqualFold(key, "upstreams"):
		return "upstreams", true
	}
	return "", false
}

// scanToken reads one token; any decode failure aborts the scan so the
// regular parse can report the malformed document.
func scanToken(dec *json.Decoder) (json.Token, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, errAbortScan
	}
	return tok, nil
}

// scanKey reads the next key of the object currently being walked.
func scanKey(dec *json.Decoder) (string, error) {
	tok, err := scanToken(dec)
	if err != nil {
		return "", err
	}
	key, ok := tok.(string)
	if !ok {
		return "", errAbortScan
	}
	return key, nil
}

// skipValue consumes one complete JSON value.
func skipValue(dec *json.Decoder) error {
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	return skipRest(dec, tok)
}

// skipRest consumes the remainder of a value whose first token is tok.
func skipRest(dec *json.Decoder, tok json.Token) error {
	delim, ok := tok.(json.Delim)
	if !ok {
		return nil // scalar, fully consumed already
	}
	var closer json.Delim
	switch delim {
	case '{':
		closer = '}'
		for dec.More() {
			if _, err := scanKey(dec); err != nil {
				return err
			}
			if err := skipValue(dec); err != nil {
				return err
			}
		}
	case '[':
		closer = ']'
		for dec.More() {
			if err := skipValue(dec); err != nil {
				return err
			}
		}
	default:
		return errAbortScan
	}
	tok, err := scanToken(dec)
	if err != nil {
		return err
	}
	if end, ok := tok.(json.Delim); !ok || end != closer {
		return errAbortScan
	}
	return nil
}

// CompareSnapshots returns the fixed-direction diff from old to new. Both
// inputs are assumed to have passed ParseSnapshot; the report is fully
// deterministic and identical for semantically identical comparisons.
func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
	oldAdj := adjacencyFromValidFile(oldSnap.Graph)
	newAdj := adjacencyFromValidFile(newSnap.Graph)

	added, removed := diffRelations(oldAdj, newAdj)

	var newNodes, removedNodes, changedNodes []string
	for name := range newAdj {
		if oldParents, ok := oldAdj[name]; !ok {
			newNodes = append(newNodes, name)
		} else if !stringSliceEqual(oldParents, newAdj[name]) {
			changedNodes = append(changedNodes, name)
		}
	}
	for name := range oldAdj {
		if _, ok := newAdj[name]; !ok {
			removedNodes = append(removedNodes, name)
		}
	}
	sort.Strings(newNodes)
	sort.Strings(removedNodes)
	sort.Strings(changedNodes)

	common := make([]string, 0)
	for name := range oldAdj {
		if _, ok := newAdj[name]; ok {
			common = append(common, name)
		}
	}
	sort.Strings(common)

	rootChanges := make([]RootSourceChange, 0)
	for _, name := range common {
		oldRoots := rootSources(name, oldAdj)
		newRoots := rootSources(name, newAdj)
		if !stringSliceEqual(oldRoots, newRoots) {
			rootChanges = append(rootChanges, RootSourceChange{
				Dataset:  name,
				OldRoots: oldRoots,
				NewRoots: newRoots,
			})
		}
	}

	return &CompareReport{
		NewDatasets:       orEmptyStrings(newNodes),
		RemovedDatasets:   orEmptyStrings(removedNodes),
		ChangedDatasets:   orEmptyStrings(changedNodes),
		AddedRelations:    orEmptyRelations(added),
		RemovedRelations:  orEmptyRelations(removed),
		RootSourceChanges: rootChanges,
	}
}

// adjacencyFromValidFile builds normalized parent adjacency from an already
// validated graph file.
func adjacencyFromValidFile(gf GraphFile) adjacency {
	adj := make(adjacency, len(gf.Datasets))
	for _, ds := range gf.Datasets {
		adj[ds.Name] = uniqueSorted(ds.Upstreams)
	}
	return adj
}

// rootSources returns the root datasets reachable from node by following
// direct upstream edges. A node without upstreams is itself a root and its own
// source, so it is included. Nodes reached by more than one path count once.
// The result is sorted by name and never nil.
func rootSources(node string, adj adjacency) []string {
	visited := make(map[string]bool)
	var roots []string
	var walk func(string)
	walk = func(current string) {
		if visited[current] {
			return
		}
		visited[current] = true
		parents := adj[current]
		if len(parents) == 0 {
			roots = append(roots, current)
			return
		}
		for _, parent := range parents {
			walk(parent)
		}
	}
	walk(node)
	sort.Strings(roots)
	return orEmptyStrings(roots)
}

func orEmptyStrings(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

func orEmptyRelations(r []Relation) []Relation {
	if r == nil {
		return []Relation{}
	}
	return r
}

// Command chainledger is the 链上数据治理与血缘工作台 entry point.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/asdhoaiqqq/chainledger-governance/chainledger"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

// run dispatches the command and returns the process exit code. Keeping the
// exit code out of main makes the CLI testable without spawning a subprocess.
func run(args []string) int {
	command := "demo"
	if len(args) > 0 {
		command = args[0]
	}
	switch command {
	case "demo":
		runDemo()
		return 0
	case "version":
		fmt.Println("chainledger 0.2.0")
		return 0
	case "preview":
		return runBatch(args[1:], false)
	case "apply":
		return runBatch(args[1:], true)
	case "snapshot":
		return runSnapshot(args[1:])
	case "compare":
		return runCompare(args[1:])
	case "trace":
		return runTrace(args[1:])
	case "help", "-h", "--help":
		usage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		return 2
	}
}

func usage() {
	fmt.Print(`usage: chainledger <command> [arguments]

commands:
  demo                        run the built-in lineage demo
  version                     print the version
  preview <graph> <plan>      validate the batch and print the report without
                              modifying the graph file
  apply <graph> <plan>        validate the batch, apply it to the graph file,
                              and print the report
  snapshot <graph> <snapshot> save a read-only versioned snapshot of the
                              current graph; an existing snapshot of the same
                              content is left byte-for-byte untouched, a
                              different or corrupt target is refused
  compare <old-snapshot> <new-snapshot>
                              read-only comparison of two snapshots; prints a
                              JSON report of nodes, relations, and root-source
                              sets that differ from the old to the new version
  trace <snapshot> <dataset>  read-only source trace of one dataset within a
                              single snapshot; prints a JSON report of every
                              reachable root source with one shortest path
  help                        show this help

The graph file is JSON:
  {"datasets": [{"name": "A", "upstreams": []}, ...]}

The plan file is JSON:
  {"changes": [{"name": "A", "upstreams": ["B"]}, ...], "removals": ["C", ...]}

The snapshot file is JSON with formatVersion 1, a semantic contentId, and the
complete graph. Its bytes depend only on graph semantics, never on record
order, upstream order, duplicate upstreams, JSON whitespace, save time, or
file path. compare and trace never write anything.

A batch registers new datasets, replaces every direct upstream of an
existing dataset with the listed upstreams, and deletes the datasets named in
removals. An empty upstream list makes the dataset a root. Datasets not
mentioned in the plan keep their upstreams. New datasets may reference each
other regardless of plan order; the final graph must be acyclic and every
upstream must resolve to a dataset in the final graph. A retained dataset
that still references a deleted name rejects the batch. Preview and apply
produce the same report for the same inputs.
`)
}

// runBatch implements preview (apply=false) and apply (apply=true). It reads
// the graph and plan JSON files, validates them, prints the report to stdout,
// and — only for apply — writes the final graph back to the graph file. Any
// failure is reported on stderr with a non-zero exit code; on failure the graph
// file is left untouched.
func runBatch(args []string, apply bool) int {
	if len(args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: chainledger %s <graph.json> <plan.json>\n", verb(apply))
		return 2
	}
	graphPath := args[0]
	planPath := args[1]

	graphData, err := os.ReadFile(graphPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read graph file %q: %v\n", graphPath, err)
		return 1
	}
	graph, err := chainledger.UnmarshalGraphFile(graphData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid graph file %q: %v\n", graphPath, err)
		return 1
	}

	planData, err := os.ReadFile(planPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read plan file %q: %v\n", planPath, err)
		return 1
	}
	plan, err := chainledger.UnmarshalPlan(planData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid plan file %q: %v\n", planPath, err)
		return 1
	}

	var report *chainledger.BatchReport
	if apply {
		report, err = chainledger.ApplyBatch(graph, plan)
	} else {
		report, err = chainledger.PreviewBatch(graph, plan)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		return 1
	}

	if apply {
		out, err := chainledger.MarshalGraphFile(graph)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot serialize final graph: %v\n", err)
			return 1
		}
		if err := atomicWrite(graphPath, out); err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot write graph file %q: %v\n", graphPath, err)
			return 1
		}
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

func verb(apply bool) string {
	if apply {
		return "apply"
	}
	return "preview"
}

// runSnapshot implements `snapshot <graph.json> <snapshot.json>`. It reads and
// validates the current graph without modifying it, builds a deterministic,
// content-addressed snapshot, and saves it.
//
// Save rules, serialized against concurrent saves by an advisory lock on a
// sibling lock file:
//   - target absent: create it atomically (temp file + rename);
//   - target present, a valid snapshot of the same content: succeed and leave
//     the existing file's bytes untouched (idempotent);
//   - target present with different content, or corrupt/unreadable: refuse and
//     never overwrite it.
//
// The content identifier is printed only after the save has committed.
func runSnapshot(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger snapshot <graph.json> <snapshot.json>")
		return 2
	}
	graphPath := args[0]
	snapshotPath := args[1]

	graphData, err := os.ReadFile(graphPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read graph file %q: %v\n", graphPath, err)
		return 1
	}
	graph, err := chainledger.UnmarshalGraphFile(graphData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid graph file %q: %v\n", graphPath, err)
		return 1
	}
	snap, err := chainledger.BuildSnapshot(graph)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot build snapshot from %q: %v\n", graphPath, err)
		return 1
	}
	data, err := chainledger.MarshalSnapshot(snap)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot serialize snapshot: %v\n", err)
		return 1
	}

	// Hold a process-wide advisory lock for the whole check-then-write so
	// concurrent saves cannot interleave between inspecting the target and
	// committing the replacement.
	lock, err := acquireLock(snapshotPath + ".lock")
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot lock snapshot target %q: %v\n", snapshotPath, err)
		return 1
	}
	defer lock.release()

	existing, err := os.ReadFile(snapshotPath)
	switch {
	case err == nil:
		oldSnap, perr := chainledger.ParseSnapshot(existing)
		if perr != nil {
			fmt.Fprintf(os.Stderr, "error: refusing to overwrite %q: existing file is not a valid snapshot: %v\n", snapshotPath, perr)
			return 1
		}
		if oldSnap.ContentID != snap.ContentID {
			fmt.Fprintf(os.Stderr, "error: refusing to overwrite %q: it already holds a different snapshot (content %s); target content would be %s\n", snapshotPath, oldSnap.ContentID, snap.ContentID)
			return 1
		}
		// Same content: success without touching the file's bytes.
	case os.IsNotExist(err):
		if err := atomicWrite(snapshotPath, data); err != nil {
			fmt.Fprintf(os.Stderr, "error: cannot write snapshot file %q: %v\n", snapshotPath, err)
			return 1
		}
	default:
		fmt.Fprintf(os.Stderr, "error: cannot inspect snapshot target %q: %v\n", snapshotPath, err)
		return 1
	}

	// The save committed (or an identical snapshot was already present); only
	// now is the content identifier reported.
	fmt.Println(snap.ContentID)
	return 0
}

// runCompare implements `compare <old.json> <new.json>`: a strictly read-only
// comparison of two snapshots that prints the deterministic JSON report to
// stdout. It never writes to either file.
func runCompare(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger compare <old-snapshot.json> <new-snapshot.json>")
		return 2
	}
	oldPath := args[0]
	newPath := args[1]

	oldData, err := os.ReadFile(oldPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read old snapshot %q: %v\n", oldPath, err)
		return 1
	}
	oldSnap, err := chainledger.ParseSnapshot(oldData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid old snapshot %q: %v\n", oldPath, err)
		return 1
	}
	newData, err := os.ReadFile(newPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read new snapshot %q: %v\n", newPath, err)
		return 1
	}
	newSnap, err := chainledger.ParseSnapshot(newData)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid new snapshot %q: %v\n", newPath, err)
		return 1
	}

	report := chainledger.CompareSnapshots(oldSnap, newSnap)
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

// runTrace implements `trace <snapshot.json> <dataset>`: a strictly read-only
// source trace against one snapshot that prints the deterministic JSON report
// to stdout. The whole snapshot is validated before the query runs; any
// failure is reported on stderr with a non-zero exit code and empty stdout,
// and the snapshot file is never modified.
func runTrace(args []string) int {
	if len(args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: chainledger trace <snapshot.json> <dataset>")
		return 2
	}
	snapshotPath := args[0]
	dataset := args[1]

	data, err := os.ReadFile(snapshotPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot read snapshot %q: %v\n", snapshotPath, err)
		return 1
	}
	snap, err := chainledger.ParseSnapshot(data)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid snapshot %q: %v\n", snapshotPath, err)
		return 1
	}

	report, err := chainledger.TraceSources(snap, dataset)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot trace %q in snapshot %q: %v\n", dataset, snapshotPath, err)
		return 1
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		fmt.Fprintf(os.Stderr, "error: cannot write report: %v\n", err)
		return 1
	}
	return 0
}

// atomicWrite writes data to a temporary file in the same directory as path
// and renames it into place, so a write failure never leaves a partially
// written graph file: the original is preserved.
func atomicWrite(path string, data []byte) error {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".chainledger-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	committed := false
	defer func() {
		if !committed {
			os.Remove(tmpName)
		}
	}()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmpName, path); err != nil {
		return err
	}
	committed = true
	return nil
}

func runDemo() {
	graph := map[string]*chainledger.Lineage{}
	register := func(dataset chainledger.Dataset, parents []string) {
		if err := chainledger.Register(graph, dataset, parents); err != nil {
			fmt.Printf("dataset=%s refused: %v\n", dataset.Name, err)
			return
		}
		fmt.Printf("dataset=%s registered parents=%v\n", dataset.Name, parents)
	}
	register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 3}, nil)
	register(chainledger.Dataset{Name: "transfers", SchemaVersion: 2}, []string{"raw-blocks"})
	register(chainledger.Dataset{Name: "wallet-daily", SchemaVersion: 1}, []string{"transfers"})
	register(chainledger.Dataset{Name: "raw-blocks", SchemaVersion: 4}, []string{"wallet-daily"})
	fmt.Println("roots:", chainledger.Roots(graph))
	fmt.Printf("datasets=%d\n", len(graph))
}

